  1→/**
  2→ * Visibility planner (P3-3, pure part).
  3→ *
  4→ * The gate acts on one field: the asset record's `visibility`. The bridge's
  5→ * team search whitelist is A ∪ B, where A is `meta list-accessible
  6→ * (visibility='team')`; an asset set to `private` drops out of A. The four
  7→ * read paths (search, get, get-by-name, files/read) share that whitelist, so
  8→ * dropping out of A is dropping out of the consumer's reach entirely.
  9→ *
 10→ * Given decisions, the baseline visibility of each asset and what the product
 11→ * reports right now, this produces the list of writes to make:
 12→ *
 13→ *   reject   → private     the gate hides what it has judged wrong
 14→ *   admit    → baseline    as entered (team)
 15→ *   pending  → baseline    the gate does not hide what it could not judge;
 16→ *                          a pending asset stays exactly as the baseline left it
 17→ *
 18→ * `reset` ignores decisions and restores the baseline for every asset — how a
 19→ * gate-off run, and the start of every gate-on run, get the same initial pool.
 20→ *
 21→ * Nothing here talks to the service; apply.sh does, and records what it read
 22→ * back. Keeping the plan pure means it is testable without a running stack.
 23→ *
 24→ * Usage (from apply.sh):
 25→ *   node plan-visibility.mjs --mode=apply|reset --baseline=gate_baseline.json --current=current.json
 26→ */
 27→
 28→import { readFileSync } from "node:fs";
 29→
 30→export const HIDDEN = "private";
 31→
 32→/**
 33→ * @param mode      "apply" | "reset"
 34→ * @param baseline  { assets: { [asset_id]: { baseline_visibility } }, decisions: [...] }
 35→ * @param current   { [asset_id]: visibility | null }   null = could not be read
 36→ */
 37→export function planVisibility({ mode, baseline, current, hide = [] }) {
 38→  if (mode !== "apply" && mode !== "reset" && mode !== "hide") throw new Error(`mode must be apply, reset or hide, got ${mode}`);
 39→  // "hide" is leave-one-out's tool: baseline for everything, private for the
 40→  // named assets, decisions ignored. Same write path, same read-back.
 41→  const hidden = new Set(hide);
 42→  if (mode === "hide" && hidden.size === 0) throw new Error("hide mode needs at least one asset id");
 43→  for (const id of hidden) {
 44→    if (!(baseline.assets ?? {})[id]) throw new Error(`cannot hide ${id}: not in the baseline`);
 45→  }
 46→  const decisions = new Map((baseline.decisions ?? []).map((d) => [d.asset_id, d]));
 47→  const changes = [];
 48→  const unchanged = [];
 49→  const unreadable = [];
 50→  const undecided = [];
 51→
 52→  for (const [assetId, row] of Object.entries(baseline.assets ?? {})) {
 53→    const base = row.baseline_visibility;
 54→    const now = current?.[assetId] ?? null;
 55→    if (now === null) {
 56→      unreadable.push(assetId);
 57→      continue;
 58→    }
 59→    let target = base;
 60→    let because = `reset to baseline (${base})`;
 61→    if (mode === "hide") {
 62→      if (hidden.has(assetId)) { target = HIDDEN; because = `leave-one-out: hidden for this run (${HIDDEN})`; }
 63→      else because = `leave-one-out: kept at baseline (${base})`;
 64→    } else if (mode === "apply") {
 65→      const d = decisions.get(assetId);
 66→      if (!d) {
 67→        undecided.push(assetId);
 68→        because = `no decision in the baseline; kept at baseline (${base})`;
 69→      } else if (d.decision === "reject") {
 70→        target = HIDDEN;
 71→        because = `gate: reject → ${HIDDEN} (${d.reasons[0]})`;
 72→      } else if (d.decision === "admit") {
 73→        because = `gate: admit → baseline (${base})`;
 74→      } else {
 75→        because = `gate: pending → baseline (${base}); the gate does not hide what it could not judge`;
 76→      }
 77→    }
 78→    if (now === target) unchanged.push({ asset_id: assetId, visibility: now, because });
 79→    else changes.push({ asset_id: assetId, from: now, to: target, because });
 80→  }
 81→  return { mode, changes, unchanged, unreadable, undecided };
 82→}
 83→
 84→export function renderPlan(plan) {
 85→  const lines = [`# visibility plan (${plan.mode})`];
 86→  for (const c of plan.changes) lines.push(`  ${c.asset_id}: ${c.from} → ${c.to}   ${c.because}`);
 87→  for (const u of plan.unchanged) lines.push(`  ${u.asset_id}: ${u.visibility} (unchanged)   ${u.because}`);
 88→  for (const id of plan.unreadable) lines.push(`  ${id}: visibility could not be read — NOT planned`);
 89→  if (plan.changes.length === 0 && plan.unreadable.length === 0) lines.push("  nothing to change");
 90→  return lines.join("\n");
 91→}
 92→
 93→if (import.meta.url === `file://${process.argv[1]}`) {
 94→  const arg = (name) => { const a = process.argv.find((x) => x.startsWith(`--${name}=`)); return a ? a.slice(name.length + 3) : null; };
 95→  const mode = arg("mode"); const baselinePath = arg("baseline"); const currentPath = arg("current");
 96→  if (!mode || !baselinePath || !currentPath) {
 97→    console.error("usage: node plan-visibility.mjs --mode=apply|reset --baseline=F --current=F [--json]");
 98→    process.exit(2);
 99→  }
100→  const plan = planVisibility({
101→    mode,
102→    baseline: JSON.parse(readFileSync(baselinePath, "utf8")),
103→    current: JSON.parse(readFileSync(currentPath, "utf8")),
104→    hide: (arg("hide") ?? "").split(",").filter(Boolean),
105→  });
106→  console.log(process.argv.includes("--json") ? JSON.stringify(plan, null, 2) : renderPlan(plan));
107→  // An unreadable asset is a failed plan: a run whose gate state is unknown is
108→  // not comparable with anything.
109→  process.exit(plan.unreadable.length > 0 ? 1 : 0);
110→}
111→

  1→/**
  2→ * Gate baseline (P4-4b): freeze the evidence and decisions that every run of
  3→ * the on/off comparison starts from.
  4→ *
  5→ * Why a frozen baseline instead of deciding live before each run: if the gate
  6→ * learned from run 1 and run 2 before run 3, the third gate-on run would face
  7→ * a different gate from the first, and the two arms would no longer share an
  8→ * initial condition. The difference between arms could then be the gate, or
  9→ * the order the runs happened in. So the preparation runs' events are frozen
 10→ * here once, the decisions are computed once, and apply.sh resets to this
 11→ * before every run. Nothing a comparison run produces feeds back into it.
 12→ *
 13→ * Inputs are run directories from run-once.sh. Each contributes its
 14→ * events.jsonl (fetched), used-events.jsonl (used) and outcome-events.jsonl
 15→ * (validated / corrected / needs_review). If a run predates the outcome judge,
 16→ * its outcomes are computed here from used-events + verdict + tokens, and the
 17→ * baseline says so.
 18→ *
 19→ * Usage:
 20→ *   node evaluation/gate/build-baseline.mjs --runs=<dir,dir,...> --snapshot=<asset-pool-snapshot.json>
 21→ *        [--visibility=<current.json from apply.sh --status>] [--tokens=F] [--decoys=F] [--now=ISO]
 22→ *        [--out=evaluation/gate/artifacts/gate_baseline.json]
 23→ */
 24→
 25→import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
 26→import { basename, dirname, join } from "node:path";
 27→import { fileURLToPath } from "node:url";
 28→import { parseJsonl } from "../provenance/build-events.mjs";
 29→import { judgeOutcome } from "../attribution/judge-outcome.mjs";
 30→import { decide } from "./decide.mjs";
 31→import { renderDecisions } from "./render-decision.mjs";
 32→
 33→const HERE = dirname(fileURLToPath(import.meta.url));
 34→export const DEFAULT_OUT = join(HERE, "artifacts", "gate_baseline.json");
 35→
 36→function readJsonl(path) {
 37→  return existsSync(path) ? parseJsonl(readFileSync(path, "utf8")) : [];
 38→}
 39→function readJson(path, fallback = null) {
 40→  return existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : fallback;
 41→}
 42→
 43→/** Collect one run directory's events; compute outcomes if the run has none on disk. */
 44→export function collectRun(dir, { tokensByAsset }) {
 45→  const runJson = readJson(join(dir, "run.json"), {});
 46→  const fetched = readJsonl(join(dir, "events.jsonl"));
 47→  const used = readJsonl(join(dir, "used-events.jsonl"));
 48→  let outcomes = readJsonl(join(dir, "outcome-events.jsonl"));
 49→  let outcomeSource = "outcome-events.jsonl";
 50→  if (outcomes.length === 0 && used.length > 0) {
 51→    const verdictDoc = readJson(join(dir, "verdict.json"), { verdict: "ERROR", attempts: [] });
 52→    const tokens = readJson(join(dir, "tokens.json"), tokensByAsset);
 53→    outcomes = judgeOutcome({ usedEvents: used, verdictDoc, tokensByAsset: tokens }).events;
 54→    outcomeSource = "computed here by judge-outcome from used-events.jsonl + verdict.json";
 55→  }
 56→  return {
 57→    run_id: runJson.run_id ?? basename(dir),
 58→    label: runJson.label ?? null,
 59→    verdict: runJson.verdict ?? null,
 60→    started_at: runJson.started_at ?? null,
 61→    outcome_source: outcomeSource,
 62→    events: [...fetched, ...used, ...outcomes],
 63→  };
 64→}
 65→
 66→export function buildBaseline({ runs, snapshot, visibility = null, tokensByAsset = {}, decoys = [], now }) {
 67→  const frozenAt = now ?? new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
 68→  const seen = new Map();
 69→  const sourceRuns = [];
 70→  for (const r of runs) {
 71→    const ids = [];
 72→    for (const e of r.events) {
 73→      if (!seen.has(e.event_id)) { seen.set(e.event_id, e); ids.push(e.event_id); }
 74→    }
 75→    sourceRuns.push({ run_id: r.run_id, label: r.label, verdict: r.verdict, started_at: r.started_at, outcome_source: r.outcome_source, event_ids: ids });
 76→  }
 77→  const events = [...seen.values()];
 78→  const decisions = decide({ events, snapshot, decoys, now: frozenAt, tokensByAsset });
 79→
 80→  const assets = {};
 81→  for (const a of snapshot.assets ?? []) {
 82→    const vis = visibility?.[a.asset_id] ?? null;
 83→    assets[a.asset_id] = {
 84→      name: a.name ?? null,
 85→      version: a.version ?? null,
 86→      producer_user_id: a.producer_user_id ?? null,
 87→      producer_agent_id: a.producer_agent_id ?? null,
 88→      // The pool as entered: every scenario asset is team-visible (enter-pool.sh
 89→      // checks it). If the live value was supplied it is recorded as read; if
 90→      // not, "team" is the contract and the source says it was not read.
 91→      baseline_visibility: vis ?? "team",
 92→      visibility_source: vis ? "read from /v3/meta/asset/get at freeze time" : "enter-pool.sh contract (not read at freeze time)",
 93→    };
 94→  }
 95→
 96→  return {
 97→    schema_version: "gate-baseline-v1",
 98→    frozen_at: frozenAt,
 99→    pool_snapshot_at: snapshot.pool_snapshot_at ?? null,
100→    team_id: snapshot.team_id ?? null,
101→    source_runs: sourceRuns,
102→    event_count: events.length,
