/**
 * Fetch one skill resource as raw bytes.
 *
 * `files/read` answers with a JSON envelope whose `data.content` is a string,
 * encoded per `data.encoding` ("base64" or "utf-8"). We ask for base64 so the
 * bytes survive the trip unchanged — a utf-8 round-trip loses anything that is
 * not valid utf-8, and an empty file must come back as an empty buffer, not as
 * a missing value.
 *
 * The upstream envelope is never swallowed: `code !== 0` is an error, and the
 * envelope's own message is what the caller sees.
 *
 * The HTTP implementation is injectable so the mapping (envelope → bytes) can
 * be tested without a running stack; callers that have no stub get the
 * platform's `fetch`.
 */
export async function fetchResource({ skillId, path, bridgeBase, fetcher = globalThis.fetch }) {
  const url = `${String(bridgeBase).replace(/\/+$/, "")}/files/read`;
  const res = await fetcher(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path, encoding: "base64" }),
  });
  const envelope = typeof res?.json === "function" ? await res.json() : res;
  if (envelope?.code !== 0) {
    throw new Error(envelope?.message ?? `files/read failed (code ${envelope?.code})`);
  }
  const { content = "", encoding } = envelope.data ?? {};
  return Buffer.from(content ?? "", encoding === "base64" ? "base64" : "utf8");
}
```

